// Gate is the layer that says what a caller may do with a request.
//
// It goes outermost, so nothing behind it has to ask again -- though most
// of what it stands for is not enforced here at all: the wall is a
// predicate and predicates belong in the query, so [Wall] is installed on
// the innermost server. What is left is the two rules that are about a
// row which does not exist yet.
//
//	s, err := app.Build(walled, core.Build(), pd.AuditBuild(), pd.GateBuild())
type Gate struct {
	apptest.Overlay
}

func NewGate(next apptest.Server) Gate {
	return Gate{apptest.NewOverlay(next)}
}

var _ apptest.Server = Gate{}

var _ enttx.Binder[apptest.Server] = Gate{}

// WithDriver answers with this stack running on `drv`, which is how several
// servers are put on one transaction.
//
// Every layer writes this and none can inherit it: an overlay holds what is
// behind it and has no way to make itself again, so a layer that did not
// write it would be missing from the rebuilt stack and the requests inside
// the transaction would go around it.
func (s Gate) WithDriver(drv dialect.Driver) (apptest.Server, error) {
	next, err := enttx.Rebind(s.Next(), drv)
	if err != nil {
		return nil, err
	}

	return NewGate(next), nil
}

// GateBuild makes a builder of this layer so that it can be stacked.
func GateBuild() apptest.Builder { return gateBuilder{} }

type gateBuilder struct{}

func (gateBuilder) Build(next apptest.Server) (apptest.Server, error) {
	return NewGate(next), nil
}

type gateTenant struct {
	Gate
	apptest.TenantServiceServer
}

func (s Gate) Tenant() apptest.TenantServiceServer {
	return gateTenant{s, s.Next().Tenant()}
}

// Add is not served. A tenant is put up by whoever runs the deployment,
// through a server this layer is not in front of.
func (s gateTenant) Add(ctx context.Context, req *apptest.TenantAddRequest) (*apptest.Tenant, error) {
	return nil, gate.ErrDeployment("put up")
}

// Erase is not served either, and it would take everything in the tenant
// with it.
func (s gateTenant) Erase(ctx context.Context, req *apptest.TenantRef) (*emptypb.Empty, error) {
	return nil, gate.ErrDeployment("taken down")
}

type gateHolder struct {
	Gate
	apptest.HolderServiceServer
}

func (s Gate) Holder() apptest.HolderServiceServer {
	return gateHolder{s, s.Next().Holder()}
}

// Add is the one thing about a holder this layer still says, and it is here
// because it is the one that is not a predicate: the row does not exist yet,
// so there is nothing to narrow. Reading one, changing one and erasing one
// are all the wall.
//
// The check is a read of the tenant **through the wall** rather than a
// comparison against the scope, which costs a query and is worth it. A
// reference names a tenant by identifier or by alias, and answering "is this
// one of mine" without a query means holding every tenant in scope in full --
// fine while that is the caller's own and wrong as soon as it is a list a
// credential or a policy narrowed to.
//
// NotFound and not a refusal, which is the same answer every other read of a
// tenant gives: that one exists is itself something a caller who may not see
// it should not be told. It also gets a tenant that simply is not there
// right, which comparing against a scope did not.
func (s gateHolder) Add(ctx context.Context, req *apptest.HolderAddRequest) (*apptest.Holder, error) {
	if _, err := gate.Actor(ctx); err != nil {
		return nil, err
	}

	if _, err := s.Gate.Next().Tenant().Get(ctx, apptest.TenantGetRequest_builder{
		Ref: req.GetTenant(),
	}.Build()); err != nil {
		if status.Code(err) == codes.NotFound {
			return nil, gate.ErrNotFound("Tenant")
		}

		return nil, err
	}

	return s.HolderServiceServer.Add(ctx, req)
}

// Audit is the layer that refuses a trail row written by hand.
//
// The RPCs exist because the trail is an entity like any other and a test is
// far plainer for having them. A deployment serves none of the ones that
// write: a trail somebody can edit is evidence of nothing.
type Audit struct {
	apptest.Overlay
}

func NewAudit(next apptest.Server) Audit {
	return Audit{apptest.NewOverlay(next)}
}

var _ apptest.Server = Audit{}
var _ enttx.Binder[apptest.Server] = Audit{}

// WithDriver answers with this stack running on `drv`; see [Gate.WithDriver].
func (s Audit) WithDriver(drv dialect.Driver) (apptest.Server, error) {
	next, err := enttx.Rebind(s.Next(), drv)
	if err != nil {
		return nil, err
	}

	return NewAudit(next), nil
}

// AuditBuild makes a builder of this layer so that it can be stacked.
func AuditBuild() apptest.Builder { return auditBuilder{} }

type auditBuilder struct{}

func (auditBuilder) Build(next apptest.Server) (apptest.Server, error) {
	return NewAudit(next), nil
}

type auditService struct {
	Audit
	apptest.AuditServiceServer
}

func (s Audit) Audit() apptest.AuditServiceServer {
	return auditService{s, s.Next().Audit()}
}

func (s auditService) Add(ctx context.Context, req *apptest.AuditAddRequest) (*apptest.Audit, error) {
	return nil, errTrail()
}

func (s auditService) Patch(ctx context.Context, req *apptest.AuditPatchRequest) (*apptest.Audit, error) {
	return nil, errTrail()
}

func (s auditService) Apply(ctx context.Context, req *apptest.AuditApplyRequest) (*apptest.Audit, error) {
	return nil, errTrail()
}

func (s auditService) Erase(ctx context.Context, req *apptest.AuditRef) (*emptypb.Empty, error) {
	return nil, errTrail()
}

// errTrail is Unimplemented and not PermissionDenied, and to everybody: it
// is not about who is asking, and no credential changes it.
func errTrail() error {
	return status.Error(codes.Unimplemented,
		"the trail is written by what happened, not by anybody asking")
}

// Recorder writes one row of the trail for every write the generated
// servers make.
//
// It is not a layer and it does not override an RPC. The servers call it
// from inside the transaction that makes the write, so the row and the
// record of it hold or fall together -- and so every RPC that changes
// anything is on the trail without anybody having listed them.
//
//	sink, err := bare.NewServer(db, bare.WithRecorder(pd.Recorder()))
func Recorder() bare.Recorder { return recorder{} }

type recorder struct{}

var _ bare.Recorder = recorder{}

// Record writes what happened. It runs inside the write's transaction, so an
// error here takes the write with it -- which is the answer wanted: a write
// that could not be accounted for did not happen.
//
// It writes through the server it was handed, which runs on that transaction
// and does not record; a recorder that recorded its own writes would not
// stop.
func (recorder) Record(ctx context.Context, s bare.Server, c bare.Change) error {
	var patch proto.Message
	if c.Patch != nil {
		patch = c.Patch
	}

	v, err := audit1.Of(ctx, c.Method, c.Key, patch)
	if err != nil {
		return err
	}

	_, err = s.Audit().Add(ctx, apptest.AuditAddRequest_builder{
		TenantId: v.Tenant.Bytes(),
		ActorId:  v.Actor.Bytes(),
		TraceId:  v.Trace,
		Action:   v.Action,
		ObjectId: v.Object.Bytes(),
		Patch:    v.Patch,
	}.Build())

	return err
}

var _ *patchpb.Patch

// WatchRecorder answers with the recorder that remembers a write for `w`.
//
// It is the other end of the hook the trail hangs off, and it wants the
// opposite thing from that moment: a trail row has to hold or fall with the
// write, so it is written there and then; an event has to be published only
// if the write survived, so nothing is published here at all.
//
//	sink, err := pd.NewSink(db, bare.WithRecorder(pd.WatchRecorder(w)))
func WatchRecorder(w *watch.Watch) bare.Recorder {
	return watchRecorder{w}
}

type watchRecorder struct {
	w *watch.Watch
}

var _ bare.Recorder = watchRecorder{}

func (r watchRecorder) Record(ctx context.Context, _ bare.Server, c bare.Change) error {
	k, err := pdid.From(keyBytes(c.Key))
	if err != nil {
		// A key this app does not make. Nothing to publish about it, and
		// nothing worth failing a write for.
		return nil
	}

	var doc []byte
	if c.Patch != nil {
		if b, err := proto.Marshal(c.Patch); err == nil {
			doc = b
		}
	}

	r.w.Note(ctx, watch.Change{
		Method: c.Method,
		By:     c.By,
		Key:    k,
		Patch:  doc,
	})

	return nil
}

// keyBytes is a key as the sixteen bytes an identifier is.
func keyBytes(v any) []byte {
	switch u := v.(type) {
	case uuid.UUID:
		return u[:]
	case [16]byte:
		return u[:]
	}

	return nil
}

// OutboxRecorder answers with the recorder that writes each write to the
// queue, inside the transaction that makes it.
//
// It is what makes an event survive a process that stops between the commit
// and the publish. `WatchRecorder` remembers in memory and an interceptor
// publishes once the handler has answered; this writes a row, and [Drain]
// publishes it whenever somebody next gets round to it -- which may be after
// a restart, and that is the whole of the point.
//
// Both, for a deployment that wants both: the first is immediate and lossy,
// the second is durable and late. A subscriber sees the same row twice and
// the second time says what the first said, since what is sent is state.
//
//	sink, err := pd.NewSink(db, bare.WithRecorder(pd.OutboxRecorder()))
func OutboxRecorder() bare.Recorder { return outboxRecorder{} }

type outboxRecorder struct{}

var _ bare.Recorder = outboxRecorder{}

// Record writes the row.
//
// Unlike the watch recorder it **refuses** when it cannot, which is the
// difference between the two in one line: this exists so that an event is
// not lost, and letting a write commit whose event could not be queued would
// lose exactly the one it was written to keep.
//
// It writes through `s.Db`, which is the client this transaction is running
// on, and not through a server: there are no RPCs on this entity, on
// purpose -- see the note in payday's outbox.proto.
func (outboxRecorder) Record(ctx context.Context, s bare.Server, c bare.Change) error {
	k, err := pdid.From(keyBytes(c.Key))
	if err != nil {
		// A key this app does not make, so there is nothing an identifier
		// could say about it and nobody could act on the event.
		return nil
	}

	var doc []byte
	if c.Patch != nil {
		b, err := proto.Marshal(c.Patch)
		if err != nil {
			return err
		}

		doc = b
	}

	var actor, tenant pdid.Id
	if f, ok := frame.From(ctx); ok {
		actor = f.Actor
		tenant = f.Tenant
	}

	return s.Db.Outbox.Create().
		SetID(pdid.New(OutboxDomain).Uuid()).
		SetTenantID(tenant.Uuid()).
		SetActorID(actor.Uuid()).
		SetMethod(c.Method).
		SetBy(c.By).
		SetObjectID(k.Uuid()).
		SetPatch(doc).
		Exec(ctx)
}

// DrainSize is how many rows one pass takes.
//
// Bounded because a queue that has been building since a broker went down is
// exactly when a pass must not try to hold all of it, and small enough that
// a pass which fails republishes little.
const DrainSize = 256

// Drain answers with the loop that publishes what the queue holds and takes
// it away.
//
// It is a [spin.Spinner], so it is handed to `spin.Run` with the stack:
//
//	go spin.Run(ctx, slices.Values([]any{pd.Drain(db, broker, time.Second)}))
//
// # It publishes before it deletes
//
// Which is the order that gives at-least-once, and the other order gives
// at-most-once. A process that stops between the two publishes those rows
// again on the next pass, and a subscriber reads the same state twice -- the
// second saying what the first said. That is only harmless because what
// travels is state and not a delta, and it is why an outbox is a table and a
// loop here rather than a project.
//
// # Two replicas publish twice
//
// Nothing here takes a lock, so two of these drain the same rows and publish
// them each. By the paragraph above that is not a correctness problem, and
// it is real work: a deployment that minds runs this on one replica, which
// is a line of wiring rather than a lease to get wrong. Said out loud here
// because the alternative is somebody discovering it from a graph.
func Drain(db *ent.Client, b watch.Broker, every time.Duration) spin.Spinner {
	return drain{db, b, every}
}

type drain struct {
	db    *ent.Client
	b     watch.Broker
	every time.Duration
}

var _ spin.Spinner = drain{}
var _ spin.Named = drain{}

func (drain) SpinName() string { return "outbox" }

func (d drain) Spin(ctx context.Context) error {
	return spin.Every(d.every, d.pass)(ctx)
}

// pass takes one batch, and keeps taking them for as long as it finds a full
// one -- otherwise a queue of ten thousand drains at one batch per tick and
// takes an hour to catch up from a minute of trouble.
//
// It answers nil for a failure rather than ending the loop, and logs it. A
// broker that is down or a database that blinked is a thing to try again;
// giving up would take the process down and stop serving requests that were
// fine. See the note on failure in `payday/spin` -- the loud direction is the
// default there, and this is one of the cases that means the other.
func (d drain) pass(ctx context.Context) error {
	for {
		n, err := d.once(ctx)
		if err != nil {
			log.From(ctx).ErrorContext(ctx, "outbox", slog.String("error", err.Error()))
			return nil
		}
		if n < DrainSize {
			return nil
		}
		if ctx.Err() != nil {
			return nil
		}
	}
}

// once publishes one batch and answers with how many rows were in it.
func (d drain) once(ctx context.Context) (int, error) {
	// Oldest first, which is the order they were written in: an identifier
	// carries the millisecond it was minted and a sequence within it, so the
	// key **is** the order and there is no column to keep in step.
	vs, err := d.db.Outbox.Query().
		Order(outbox.ByID()).
		Limit(DrainSize).
		All(ctx)
	if err != nil {
		return 0, err
	}
	if len(vs) == 0 {
		return 0, nil
	}

	ks := make([]uuid.UUID, len(vs))
	for i, v := range vs {
		ks[i] = v.ID
		d.b.Publish(ctx, watch.Event{
			Actor:  pdid.Id(v.ActorID),
			Tenant: pdid.Id(v.TenantID),
			Method: v.Method,
			Changes: []watch.Change{{
				Method: v.Method,
				By:     v.By,
				Key:    pdid.Id(v.ObjectID),
				Patch:  v.Patch,
			}},
		})
	}

	// And only then. A row deleted before it was published is an event that
	// nothing will ever say again.
	if _, err := d.db.Outbox.Delete().
		Where(outbox.IDIn(ks...)).
		Exec(ctx); err != nil {
		return 0, err
	}

	return len(vs), nil
}
